import { Link, useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "../../contexto/AuthContext";

export default function BarraNavegacion() {
  const { isAuth, user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const handleLogout = async () => {
    try {
      await logout();
    } finally {
      navigate("/login", { replace: true });
    }
  };

  const estaEnLogin = location.pathname === "/login";

  return (
    <nav className="navbar navbar-expand-lg bg-body-tertiary border-bottom">
      <div className="container">
        <Link className="navbar-brand" to="/">Sistema PIE</Link>

        <button
          className="navbar-toggler"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#navPrincipal"
          aria-controls="navPrincipal"
          aria-expanded="false"
          aria-label="Toggle navigation"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        <div id="navPrincipal" className="collapse navbar-collapse">
          <ul className="navbar-nav ms-auto align-items-center gap-2">
            <li className="nav-item">
              <Link className="nav-link" to="/sostenedor">
                Datos Institucional
              </Link>
            </li>

            {isAuth ? (
              <>
                {/* (Opcional) Mostrar el usuario logueado */}
                {user?.email && (
                  <li className="nav-item d-none d-lg-block">
                    <span className="navbar-text small text-secondary">
                      {user.email}
                    </span>
                  </li>
                )}
                <li className="nav-item">
                  <button
                    type="button"
                    className="btn btn-outline-secondary btn-sm ms-lg-2"
                    onClick={handleLogout}
                  >
                    Cerrar sesión
                  </button>
                </li>
              </>
            ) : (
              !estaEnLogin && (
                <li className="nav-item">
                  <Link className="nav-link" to="/login">
                    Login
                  </Link>
                </li>
              )
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
}
